    document.addEventListener('alpine:init', () => {
      window.Alpine.store('blog', { cat: 'All', q: '' });
      window.Alpine.data('inlineNewsletter', () => ({
        email: '', loading: false, subscribed: false, honeypot: '', invalid: false,
        validate() { this.invalid = this.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(this.email); },
        async submit(e) {
          this.validate();
          if (this.invalid || !this.email) return;
          if (this.honeypot) { this.subscribed = true; return; }
          this.loading = true;
          try {
            const fd = new FormData();
            fd.append('email', this.email);
            fd.append('csrf_token', document.cookie.match(/sts_csrf=([^;]+)/)?.[1] || '');
            const r = await fetch('/api/newsletter.php', { method: 'POST', body: fd, credentials: 'include' });
            const j = await r.json().catch(() => ({}));
            if (r.ok && j.ok) {
              this.subscribed = true;
              window.stsToast?.('Subscribed — check your inbox.', 'success');
            } else {
              window.stsToast?.((j && j.error) || 'Could not subscribe.', 'error');
            }
          } catch {
            window.stsToast?.('Network error. Please try again.', 'error');
          } finally { this.loading = false; }
        },
      }));
      window.Alpine.data('blogFilter', () => ({
        get cat() { return Alpine.store('blog').cat; },
        set cat(v) { Alpine.store('blog').cat = v; },
        get q() { return Alpine.store('blog').q; },
        set q(v) { Alpine.store('blog').q = v; },
        filtered() {
          let list = this.cat === 'All' ? BLOG_POSTS : BLOG_POSTS.filter(p => p.cat === this.cat);
          const q = (this.q || '').trim().toLowerCase();
          if (q.length > 1) {
            list = list.filter(p =>
              p.title.toLowerCase().includes(q) ||
              p.excerpt.toLowerCase().includes(q) ||
              (p.author || '').toLowerCase().includes(q) ||
              (p.cat || '').toLowerCase().includes(q)
            );
          }
          return list;
        },
        isFeatured(slug) {
          const list = this.filtered();
          return list.length > 0 && list[0].slug === slug;
        },
        isInGrid(slug) {
          const list = this.filtered();
          return list.length > 1 && list.slice(1).some(p => p.slug === slug);
        },
      }));
    });
  })();</script>
